		struct page *page;
		pgoff_t index;
		unsigned long offset;
		unsigned long bytes;
		size_t copied;

		offset = (pos & (PAGE_CACHE_SIZE - 1));
		index = pos >> PAGE_CACHE_SHIFT;
		bytes = min_t(unsigned long, PAGE_CACHE_SIZE - offset, iov_iter_count(i));

		if (unlikely(iov_iter_fault_in_readable(i, bytes))) {
