		pagefault_disable();
		copied = iov_iter_copy_from_user_atomic(page, i, offset, bytes);
		pagefault_enable();
		flush_dcache_page(page);
		status = a_ops->write_end(file, mapping, pos, bytes, copied, page, fsdata);
